// ----- scripts/lib/assignment.js -----
/**
 * Agent assignment engine.
 *
 * CANONICAL SOURCE. Unit-tested (tests/assignment/assignment.test.js) and
 * injected into n8n Code nodes by scripts/setup/build-workflows.js.
 *
 * The engine is a PURE FUNCTION of (agents, options) -> decision. It performs
 * no I/O. That is deliberate:
 *   - it is exhaustively testable without Google Sheets or Meta,
 *   - the strategy can change (LEAST_OPEN_CONVERSATIONS -> ROUND_ROBIN) without
 *     touching persistence,
 *   - when the store moves to PostgreSQL, only the caller changes: it will wrap
 *     this call in `SELECT ... FOR UPDATE` / a transaction. See
 *     docs/GOOGLE_SHEETS_TO_POSTGRES.md.
 *
 * See docs/ASSIGNMENT_ALGORITHM.md for the full specification, including the
 * concurrency limitations of Google Sheets as a state store.
 */


const STRATEGIES = {
  LEAST_OPEN_CONVERSATIONS: 'LEAST_OPEN_CONVERSATIONS',
  ROUND_ROBIN: 'ROUND_ROBIN',
};

/** Machine-readable reasons an agent was excluded, recorded for audit. */
const INELIGIBLE = {
  INACTIVE: 'INACTIVE',
  UNAVAILABLE: 'UNAVAILABLE',
  AT_CAPACITY: 'AT_CAPACITY',
  MALFORMED_RECORD: 'MALFORMED_RECORD',
  OUTSIDE_WORKING_HOURS: 'OUTSIDE_WORKING_HOURS',
};

const NO_AGENT_REASON = {
  NO_AGENTS_CONFIGURED: 'NO_AGENTS_CONFIGURED',
  NO_ELIGIBLE_AGENT: 'NO_ELIGIBLE_AGENT',
};

/**
 * Google Sheets returns everything as strings. 'TRUE'/'true'/'1'/'yes' are all
 * truthy in practice because humans edit these cells by hand. Anything
 * unrecognised is treated as FALSE (fail closed: do not route a customer to an
 * agent whose availability we cannot positively confirm).
 */
function parseBoolean(value, defaultValue) {
  if (value === undefined || value === null || value === '') {
    return defaultValue === undefined ? false : defaultValue;
  }
  if (typeof value === 'boolean') return value;
  const v = String(value).trim().toLowerCase();
  if (['true', '1', 'yes', 'y', 'نعم'].indexOf(v) !== -1) return true;
  if (['false', '0', 'no', 'n', 'لا'].indexOf(v) !== -1) return false;
  return defaultValue === undefined ? false : defaultValue;
}

/**
 * Sheets cells arrive as strings and may be blank. Returns `fallback` when the
 * value is not a finite number, so a typo in a spreadsheet cell cannot produce
 * NaN comparisons that silently reorder the queue.
 */
function parseIntSafe(value, fallback) {
  if (value === undefined || value === null || String(value).trim() === '') {
    return fallback;
  }
  const n = Number(String(value).trim());
  if (!isFinite(n)) return fallback;
  return Math.trunc(n);
}

/**
 * Parse an ISO-8601 timestamp to epoch ms. Invalid/blank -> null, which sorts
 * FIRST in the tie-breaker (an agent who has never been assigned should get
 * the next conversation ahead of one who was assigned an hour ago).
 */
function parseTimestamp(value) {
  if (value === undefined || value === null || String(value).trim() === '') return null;
  const t = Date.parse(String(value).trim());
  return isNaN(t) ? null : t;
}

/**
 * Normalize one raw agent row (as read from Google Sheets) into a typed record,
 * and decide eligibility. Never throws on a malformed row — marks it ineligible
 * with MALFORMED_RECORD so one bad spreadsheet row cannot break routing for
 * everyone.
 */
function evaluateAgent(rawAgent, options) {
  const opts = options || {};
  const agent = {
    agent_id: rawAgent && rawAgent.agent_id !== undefined ? String(rawAgent.agent_id).trim() : '',
    name: rawAgent && rawAgent.name !== undefined ? String(rawAgent.name).trim() : '',
    phone: rawAgent && rawAgent.phone !== undefined ? String(rawAgent.phone).trim() : '',
    role: rawAgent && rawAgent.role !== undefined ? String(rawAgent.role).trim() : '',
    active: parseBoolean(rawAgent ? rawAgent.active : undefined, false),
    available: parseBoolean(rawAgent ? rawAgent.available : undefined, false),
    max_open_conversations: parseIntSafe(
      rawAgent ? rawAgent.max_open_conversations : undefined,
      opts.defaultMaxOpenConversations === undefined ? 5 : opts.defaultMaxOpenConversations
    ),
    open_conversations: parseIntSafe(rawAgent ? rawAgent.open_conversations : undefined, 0),
    last_assigned_at_ms: parseTimestamp(rawAgent ? rawAgent.last_assigned_at : undefined),
    last_assigned_at: rawAgent && rawAgent.last_assigned_at ? String(rawAgent.last_assigned_at) : null,
    _raw: rawAgent,
  };

  const ineligibleReasons = [];

  if (!agent.agent_id) {
    ineligibleReasons.push(INELIGIBLE.MALFORMED_RECORD);
  }
  if (!agent.active) ineligibleReasons.push(INELIGIBLE.INACTIVE);
  if (!agent.available) ineligibleReasons.push(INELIGIBLE.UNAVAILABLE);

  // Capacity: a negative or zero max means "cannot take conversations".
  if (agent.max_open_conversations <= 0) {
    ineligibleReasons.push(INELIGIBLE.AT_CAPACITY);
  } else if (agent.open_conversations >= agent.max_open_conversations) {
    ineligibleReasons.push(INELIGIBLE.AT_CAPACITY);
  }

  agent.eligible = ineligibleReasons.length === 0;
  agent.ineligible_reasons = ineligibleReasons;
  return agent;
}

/**
 * Deterministic comparator implementing the documented tie-breaker chain:
 *   1. fewest open_conversations
 *   2. earliest last_assigned_at (never-assigned sorts first)
 *   3. agent_id ascending (lexicographic, stable + deterministic fallback)
 *
 * Step 3 guarantees that two n8n executions given identical agent state pick
 * the SAME agent, which makes the behaviour reproducible in tests and in
 * incident review. It does not by itself prevent double-assignment under
 * concurrency — see docs/ASSIGNMENT_ALGORITHM.md.
 */
function compareLeastOpen(a, b) {
  if (a.open_conversations !== b.open_conversations) {
    return a.open_conversations - b.open_conversations;
  }
  const aTs = a.last_assigned_at_ms;
  const bTs = b.last_assigned_at_ms;
  if (aTs === null && bTs !== null) return -1;
  if (aTs !== null && bTs === null) return 1;
  if (aTs !== null && bTs !== null && aTs !== bTs) return aTs - bTs;
  if (a.agent_id < b.agent_id) return -1;
  if (a.agent_id > b.agent_id) return 1;
  return 0;
}

/**
 * ROUND_ROBIN comparator — provided so the strategy is genuinely pluggable
 * rather than aspirational. Selects the agent whose last assignment is oldest,
 * ignoring current load (capacity is still enforced during eligibility).
 */
function compareRoundRobin(a, b) {
  const aTs = a.last_assigned_at_ms;
  const bTs = b.last_assigned_at_ms;
  if (aTs === null && bTs !== null) return -1;
  if (aTs !== null && bTs === null) return 1;
  if (aTs !== null && bTs !== null && aTs !== bTs) return aTs - bTs;
  if (a.agent_id < b.agent_id) return -1;
  if (a.agent_id > b.agent_id) return 1;
  return 0;
}

const COMPARATORS = {
  [STRATEGIES.LEAST_OPEN_CONVERSATIONS]: compareLeastOpen,
  [STRATEGIES.ROUND_ROBIN]: compareRoundRobin,
};

/**
 * Select the agent who should receive a new conversation.
 *
 * @param {Array<object>} rawAgents  Rows from the Agents sheet (strings are fine).
 * @param {object} [options]
 * @param {string} [options.strategy='LEAST_OPEN_CONVERSATIONS']
 * @param {number} [options.defaultMaxOpenConversations=5]
 * @returns {{
 *   assigned: boolean,
 *   agent: object|null,
 *   status: 'ASSIGNED'|'WAITING_FOR_AGENT',
 *   reason: string|null,
 *   strategy: string,
 *   candidates: Array<object>,   // eligible agents, in selection order
 *   evaluated: Array<object>,    // every agent + why they were excluded
 *   decided_at: string           // ISO timestamp of the decision
 * }}
 *
 * When no agent is eligible the conversation is NOT dropped: the caller must
 * persist status WAITING_FOR_AGENT together with `reason`, and the unassigned
 * queue is retried by the reassignment workflow.
 */
function selectAgent(rawAgents, options) {
  const opts = options || {};
  const strategy = opts.strategy || STRATEGIES.LEAST_OPEN_CONVERSATIONS;
  const comparator = COMPARATORS[strategy] || compareLeastOpen;
  const decidedAt = opts.now ? new Date(opts.now).toISOString() : new Date().toISOString();

  const list = Array.isArray(rawAgents) ? rawAgents : [];
  const evaluated = list.map((a) => evaluateAgent(a, opts));

  if (evaluated.length === 0) {
    return {
      assigned: false,
      agent: null,
      status: 'WAITING_FOR_AGENT',
      reason: NO_AGENT_REASON.NO_AGENTS_CONFIGURED,
      strategy,
      candidates: [],
      evaluated,
      decided_at: decidedAt,
    };
  }

  const candidates = evaluated.filter((a) => a.eligible).sort(comparator);

  if (candidates.length === 0) {
    return {
      assigned: false,
      agent: null,
      status: 'WAITING_FOR_AGENT',
      reason: NO_AGENT_REASON.NO_ELIGIBLE_AGENT,
      strategy,
      candidates: [],
      evaluated,
      decided_at: decidedAt,
    };
  }

  return {
    assigned: true,
    agent: candidates[0],
    status: 'ASSIGNED',
    reason: null,
    strategy,
    candidates,
    evaluated,
    decided_at: decidedAt,
  };
}

// ----- scripts/lib/conversation.js -----
/**
 * Conversation lifecycle: identity, state machine, and field derivation.
 *
 * CANONICAL SOURCE. Unit-tested (tests/conversations/conversation.test.js) and
 * injected into n8n Code nodes by scripts/setup/build-workflows.js.
 *
 * Full semantics for every state and transition: docs/ARCHITECTURE.md
 * ("Conversation State Machine"). Every state here has documented meaning —
 * no state exists that the docs do not explain.
 */


/**
 * Conversation states.
 *
 * The MVP deliberately uses SIX states, not the eight suggested, because two
 * pairs collapse without losing information:
 *   - OPEN is not a distinct state: it is the union of every non-CLOSED state.
 *     Managers filter "open" with `status != CLOSED`. Keeping OPEN alongside
 *     ASSIGNED/UNANSWERED would allow contradictory rows (OPEN *and* UNANSWERED).
 *   - ASSIGNED collapses into UNANSWERED: the instant a conversation is assigned
 *     it is by definition awaiting the agent's first reply. A separate ASSIGNED
 *     state would be entered and left in the same execution, so it could never
 *     be observed and would only create ambiguity.
 * This is recorded as a decision in docs/DECISIONS.md.
 */
const STATUS = {
  /** Created but no eligible agent existed. Sits in the unassigned queue. */
  WAITING_FOR_AGENT: 'WAITING_FOR_AGENT',
  /** Assigned to an agent; the customer's latest message has no agent reply yet. */
  UNANSWERED: 'UNANSWERED',
  /** Agent has replied and their reply is the most recent message. */
  REPLIED: 'REPLIED',
  /** Alias of REPLIED from the manager's point of view: ball is in customer's court. */
  WAITING_FOR_CUSTOMER: 'WAITING_FOR_CUSTOMER',
  /** Explicitly ended. Only a human/automation closes; customers never close. */
  CLOSED: 'CLOSED',
};

/** States that count against an agent's open-conversation capacity. */
const OPEN_STATUSES = [
  STATUS.WAITING_FOR_AGENT,
  STATUS.UNANSWERED,
  STATUS.REPLIED,
  STATUS.WAITING_FOR_CUSTOMER,
];

/** Events that drive transitions. */
const EVENT = {
  CUSTOMER_MESSAGE: 'CUSTOMER_MESSAGE',
  AGENT_MESSAGE: 'AGENT_MESSAGE',
  AGENT_ASSIGNED: 'AGENT_ASSIGNED',
  NO_AGENT_AVAILABLE: 'NO_AGENT_AVAILABLE',
  CLOSE: 'CLOSE',
  REOPEN: 'REOPEN',
};

function isOpenStatus(status) {
  return OPEN_STATUSES.indexOf(status) !== -1;
}

/**
 * Generate a stable internal conversation id.
 *
 * Deliberately NOT the WhatsApp message id: message ids are per-message and
 * change with every message, so using one as a conversation key would create a
 * new "conversation" for every inbound message.
 *
 * Format: CONV-<businessPhoneNumberId>-<customerPhone>-<epochMillis>
 * The business number is part of the key so the same customer messaging two
 * different business numbers yields two independent conversations.
 *
 * The timestamp suffix makes ids unique across REOPEN cycles (a customer who
 * returns after a conversation was closed gets a genuinely new conversation
 * row, preserving the closed one for history).
 */
function generateConversationId(businessPhoneNumberId, customerPhone, nowMs) {
  const ts = nowMs === undefined || nowMs === null ? Date.now() : Number(nowMs);
  const biz = String(businessPhoneNumberId || 'unknown').replace(/[^A-Za-z0-9]/g, '');
  const cust = String(customerPhone || 'unknown').replace(/[^A-Za-z0-9]/g, '');
  return 'CONV-' + biz + '-' + cust + '-' + ts;
}

/**
 * Decide the next state given the current state and an event.
 *
 * Returns the transition rather than mutating, so it is trivially testable and
 * the caller decides how to persist it.
 *
 * @param {string|null} currentStatus  null/'' means "no existing conversation".
 * @param {string} event               One of EVENT.*
 * @param {object} [ctx]
 * @param {boolean} [ctx.reopenClosed=true]  Whether a customer message on a
 *        CLOSED conversation reopens it (see docs/ARCHITECTURE.md).
 * @param {boolean} [ctx.hasAgent=false]     Whether an agent is assigned.
 * @returns {{ next: string, changed: boolean, reason: string }}
 */
function nextStatus(currentStatus, event, ctx) {
  const options = ctx || {};
  const reopenClosed = options.reopenClosed === undefined ? true : !!options.reopenClosed;
  const hasAgent = !!options.hasAgent;
  const current = currentStatus || null;

  const result = (next, reason) => ({
    next,
    changed: next !== current,
    reason,
  });

  switch (event) {
    case EVENT.CUSTOMER_MESSAGE: {
      // A customer message always means the business owes a reply.
      if (current === null) {
        return result(
          hasAgent ? STATUS.UNANSWERED : STATUS.WAITING_FOR_AGENT,
          'new_conversation_from_customer_message'
        );
      }
      if (current === STATUS.CLOSED) {
        if (!reopenClosed) {
          // Configured not to auto-reopen: stay closed, caller creates a new
          // conversation instead.
          return result(STATUS.CLOSED, 'closed_conversation_not_reopened_by_config');
        }
        return result(
          hasAgent ? STATUS.UNANSWERED : STATUS.WAITING_FOR_AGENT,
          'reopened_by_customer_message'
        );
      }
      if (current === STATUS.WAITING_FOR_AGENT) {
        // Still nobody to route to; more messages don't change that.
        return result(STATUS.WAITING_FOR_AGENT, 'still_awaiting_agent');
      }
      // REPLIED / WAITING_FOR_CUSTOMER / UNANSWERED -> the customer spoke last.
      return result(STATUS.UNANSWERED, 'customer_message_awaiting_agent_reply');
    }

    case EVENT.AGENT_ASSIGNED: {
      if (current === STATUS.CLOSED) {
        return result(STATUS.CLOSED, 'cannot_assign_closed_conversation');
      }
      return result(STATUS.UNANSWERED, 'agent_assigned_awaiting_first_reply');
    }

    case EVENT.NO_AGENT_AVAILABLE: {
      if (current === STATUS.CLOSED) {
        return result(STATUS.CLOSED, 'closed_conversation_unchanged');
      }
      return result(STATUS.WAITING_FOR_AGENT, 'no_eligible_agent');
    }

    case EVENT.AGENT_MESSAGE: {
      if (current === STATUS.CLOSED) {
        // An agent messaging a closed conversation reopens it — they are
        // deliberately re-engaging the customer.
        return result(STATUS.REPLIED, 'reopened_by_agent_message');
      }
      return result(STATUS.REPLIED, 'agent_replied');
    }

    case EVENT.CLOSE:
      return result(STATUS.CLOSED, 'closed');

    case EVENT.REOPEN: {
      if (current !== STATUS.CLOSED) {
        return result(current, 'reopen_ignored_not_closed');
      }
      return result(
        hasAgent ? STATUS.UNANSWERED : STATUS.WAITING_FOR_AGENT,
        'manually_reopened'
      );
    }

    default:
      return result(current === null ? STATUS.WAITING_FOR_AGENT : current, 'unknown_event');
  }
}

/**
 * Build the full Conversations row for a brand-new conversation.
 * Field names match docs/GOOGLE_SHEETS_SCHEMA.md exactly (snake_case).
 */
function buildNewConversationRow(input) {
  const i = input || {};
  const nowIso = i.now_iso || new Date().toISOString();
  const conversationId =
    i.conversation_id ||
    generateConversationId(i.business_phone_number_id, i.customer_phone, Date.parse(nowIso));

  return {
    conversation_id: conversationId,
    customer_phone: i.customer_phone || '',
    customer_name: i.customer_name || '',
    business_phone_number_id: i.business_phone_number_id || '',
    assigned_agent_id: i.assigned_agent_id || '',
    assigned_agent_name: i.assigned_agent_name || '',
    status: i.status || STATUS.WAITING_FOR_AGENT,
    last_message: i.last_message || '',
    last_message_id: i.last_message_id || '',
    last_message_direction: i.last_message_direction || 'inbound',
    last_customer_message_at: i.last_customer_message_at || nowIso,
    last_agent_message_at: '',
    last_activity_at: nowIso,
    unread: i.unread === undefined ? 'TRUE' : i.unread ? 'TRUE' : 'FALSE',
    created_at: nowIso,
    updated_at: nowIso,
    closed_at: '',
    wa_link: i.wa_link || '',
    // Why the conversation is unassigned, when it is. Empty when assigned.
    unassigned_reason: i.unassigned_reason || '',
  };
}

/**
 * Compute the field updates to apply to an existing conversation when a new
 * inbound customer message arrives. Returns ONLY changed fields, so the caller
 * writes a minimal update (fewer Sheets cells touched = fewer lost concurrent
 * edits).
 */
function buildCustomerMessageUpdate(existing, message, opts) {
  const options = opts || {};
  const nowIso = options.now_iso || new Date().toISOString();
  const current = existing || {};
  const transition = nextStatus(current.status || null, EVENT.CUSTOMER_MESSAGE, {
    reopenClosed: options.reopenClosed,
    hasAgent: !!(current.assigned_agent_id && String(current.assigned_agent_id).trim()),
  });

  const update = {
    status: transition.next,
    last_message: message.preview || message.text || '',
    last_message_id: message.message_id || '',
    last_message_direction: 'inbound',
    last_customer_message_at: message.timestamp_iso || nowIso,
    last_activity_at: message.timestamp_iso || nowIso,
    unread: 'TRUE',
    updated_at: nowIso,
  };

  // Reopening clears the closure timestamp.
  if (current.status === STATUS.CLOSED && transition.next !== STATUS.CLOSED) {
    update.closed_at = '';
  }

  // Refresh the profile name if WhatsApp now gives us one and we had none.
  if (message.customer_name && !current.customer_name) {
    update.customer_name = message.customer_name;
  }

  return { update, transition };
}

/**
 * Compute updates for an outbound agent message that the API accepted.
 * NOTE: 'accepted by the API' is NOT 'delivered to the customer' — delivery is
 * only known from a later status webhook. See docs/ERROR_HANDLING.md.
 */
function buildAgentMessageUpdate(existing, message, opts) {
  const options = opts || {};
  const nowIso = options.now_iso || new Date().toISOString();
  const current = existing || {};
  const transition = nextStatus(current.status || null, EVENT.AGENT_MESSAGE, {
    hasAgent: true,
  });

  const update = {
    status: transition.next,
    last_message: message.preview || message.text || '',
    last_message_id: message.message_id || '',
    last_message_direction: 'outbound',
    last_agent_message_at: message.timestamp_iso || nowIso,
    last_activity_at: message.timestamp_iso || nowIso,
    // The agent has now seen and answered the customer.
    unread: 'FALSE',
    updated_at: nowIso,
  };

  if (current.status === STATUS.CLOSED) {
    update.closed_at = '';
  }

  return { update, transition };
}

/**
 * Determine whether a conversation is eligible for inactivity-based closing.
 * The MVP does NOT auto-close: this only marks eligibility so a human or an
 * explicitly enabled scheduled workflow can act. See docs/DECISIONS.md.
 */
function isInactivityCloseEligible(conversation, opts) {
  const options = opts || {};
  const hours = Number(options.inactivityHours);
  const nowMs = options.now ? new Date(options.now).getTime() : Date.now();
  const c = conversation || {};

  if (!isFinite(hours) || hours <= 0) {
    return { eligible: false, reason: 'INACTIVITY_DISABLED' };
  }
  if (!isOpenStatus(c.status)) {
    return { eligible: false, reason: 'NOT_OPEN' };
  }
  const lastActivity = c.last_activity_at ? Date.parse(String(c.last_activity_at)) : NaN;
  if (isNaN(lastActivity)) {
    return { eligible: false, reason: 'NO_VALID_LAST_ACTIVITY' };
  }
  const idleHours = (nowMs - lastActivity) / 3600000;
  if (idleHours < hours) {
    return { eligible: false, reason: 'STILL_ACTIVE', idle_hours: idleHours };
  }
  return { eligible: true, reason: 'INACTIVE_BEYOND_THRESHOLD', idle_hours: idleHours };
}

// ===================== end generated block ================================

const waiting = $('Read Waiting Conversations').all()
  .map((i) => i.json)
  .filter((c) => c && c.conversation_id && c.status === 'WAITING_FOR_AGENT')
  // Oldest first: nobody should be stuck at the back of the queue.
  .sort((a, b) => Date.parse(a.created_at || 0) - Date.parse(b.created_at || 0));

const agents = $input.all().map((i) => i.json).filter((a) => a && a.agent_id);
const strategy = $env.ASSIGNMENT_STRATEGY || 'LEAST_OPEN_CONVERSATIONS';

if (waiting.length === 0) {
  console.log(JSON.stringify({ event: 'queue_retry', waiting: 0, assigned: 0 }));
  return [];
}

// Work on a mutable copy so each assignment within this run is
// reflected in the next agent's load — otherwise a single run would
// hand the whole queue to the same least-loaded agent.
const workingAgents = agents.map((a) => Object.assign({}, a));
const results = [];
const nowIso = new Date().toISOString();

for (const conversation of waiting) {
  const decision = selectAgent(workingAgents, { strategy });
  if (!decision.assigned) {
    // Still nobody available — leave it queued and stop trying.
    console.log(JSON.stringify({
      event: 'queue_retry_exhausted',
      remaining: waiting.length - results.length,
      reason: decision.reason,
    }));
    break;
  }

  const chosen = decision.agent;

  // Reflect the assignment locally before the next iteration.
  const idx = workingAgents.findIndex((a) => String(a.agent_id) === String(chosen.agent_id));
  if (idx !== -1) {
    workingAgents[idx] = Object.assign({}, workingAgents[idx], {
      open_conversations: chosen.open_conversations + 1,
      last_assigned_at: nowIso,
    });
  }

  results.push({ json: {
    conversation_id: conversation.conversation_id,
    assigned_agent_id: chosen.agent_id,
    assigned_agent_name: chosen.name,
    status: 'UNANSWERED',
    unassigned_reason: '',
    updated_at: nowIso,
    agent_open_after: chosen.open_conversations + 1,
    assigned_at: nowIso,
  } });
}

console.log(JSON.stringify({
  event: 'queue_retry',
  waiting: waiting.length,
  assigned: results.length,
}));

return results;
